async def act(page):
    # Try to expand a price-related section if it exists
    price_section_button = page.get_by_role('button', name='Price', exact=False)
    if await price_section_button.count() > 0:
        await price_section_button.click()
        await page.wait_for_timeout(1000)  # Wait for section to expand

    # Locate the price input field using accessibility roles
    price_field = page.get_by_role('textbox', name='price', exact=False)
    if await price_field.count() == 0:
        # If not found, try alternative accessibility-based search
        # Look for any textbox that might be related to price
        all_textboxes = page.get_by_role('textbox')
        count = await all_textboxes.count()
        for i in range(count):
            textbox = all_textboxes.nth(i)
            placeholder = await textbox.get_attribute('placeholder')
            if placeholder and 'price' in placeholder.lower():
                price_field = textbox
                break

    if await price_field.count() > 0:
        current_price = await price_field.input_value()
        if current_price:
            try:
                current_price_float = float(current_price)
                new_price = current_price_float * 0.9
                await price_field.fill(str(new_price))
                # Save the changes
                save_button = page.get_by_role('button', name='Save')
                if await save_button.count() > 0:
                    await save_button.click()
                    await page.wait_for_timeout(2000)  # Wait for save to complete
                else:
                    return "Save button not found. Changes may not be saved."
            except ValueError:
                return "Failed to parse price value. Ensure it's a number."
        else:
            return "Price field is empty. Cannot reduce price."
    else:
        return "Price input field not found on the page."

